body.script:
window.dtscLiffReady = liff.init({ liffId: document.body.dataset.liffId });
window.dtscLiffReady.catch(function (err) {
	console.error(err);
	alert("LIFF 初始化失敗：" + err.message);
});

t.script:

(function () {
	const fileInput = document.getElementById("files");
	const MAX_FILES = parseInt(fileInput.dataset.max, 10) || 5;
	const MAX_PDF_BYTES = 10 * 1024 * 1024;
	let idToken = null;
	let selectedFiles = [];

	function showError(msg) {
		const box = document.getElementById("error_box");
		box.textContent = msg || "";
		box.style.display = msg ? "block" : "none";
	}

	function today() {
		const d = new Date();
		d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
		return d.toISOString().slice(0, 10);
	}

	function postJSON(url, payload) {
		return fetch(url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(Object.assign({ id_token: idToken }, payload)),
		}).then(function (resp) { return resp.json(); });
	}

	function switchTab(name) {
		document.querySelectorAll(".dtsc-tab").forEach(function (btn) {
			btn.classList.toggle("active", btn.dataset.tab === name);
		});
		document.getElementById("tab_apply").style.display = name === "apply" ? "" : "none";
		document.getElementById("tab_list").style.display = name === "list" ? "" : "none";
		if (name === "list") {
			loadList();
		}
	}

	function renderFiles() {
		const list = document.getElementById("file_list");
		list.innerHTML = "";
		selectedFiles.forEach(function (file, index) {
			const li = document.createElement("li");
			const name = document.createElement("span");
			name.textContent = file.name;
			const remove = document.createElement("button");
			remove.type = "button";
			remove.textContent = "移除";
			remove.addEventListener("click", function () {
				selectedFiles.splice(index, 1);
				renderFiles();
			});
			li.appendChild(name);
			li.appendChild(remove);
			list.appendChild(li);
		});
	}

	function readAsDataURL(blob) {
		return new Promise(function (resolve, reject) {
			const reader = new FileReader();
			reader.onload = function () { resolve(reader.result); };
			reader.onerror = reject;
			reader.readAsDataURL(blob);
		});
	}

	// 手機照片動輒數 MB，先縮成長邊 1600px 的 JPEG 再上傳
	function compressImage(file) {
		return new Promise(function (resolve, reject) {
			const url = URL.createObjectURL(file);
			const img = new Image();
			img.onload = function () {
				const scale = Math.min(1, 1600 / Math.max(img.width, img.height));
				const canvas = document.createElement("canvas");
				canvas.width = Math.round(img.width * scale);
				canvas.height = Math.round(img.height * scale);
				canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
				URL.revokeObjectURL(url);
				resolve(canvas.toDataURL("image/jpeg", 0.8));
			};
			img.onerror = function () {
				URL.revokeObjectURL(url);
				reject(new Error("無法讀取圖片：" + file.name));
			};
			img.src = url;
		});
	}

	async function encodeFile(file) {
		if (file.type === "application/pdf") {
			if (file.size > MAX_PDF_BYTES) {
				throw new Error(file.name + " 超過 10MB");
			}
			const pdfData = await readAsDataURL(file);
			return { name: file.name, type: "application/pdf", data: pdfData.split(",")[1] };
		}
		const imageData = await compressImage(file);
		const name = file.name.replace(/\.[^.]+$/, "") + ".jpg";
		return { name: name, type: "image/jpeg", data: imageData.split(",")[1] };
	}

	function loadList() {
		const box = document.getElementById("list_box");
		box.textContent = "載入中...";
		postJSON("/liff_app/api/expense/list", {}).then(function (result) {
			if (!result.success) {
				box.textContent = result.message;
				return;
			}
			if (!result.data.length) {
				box.textContent = "目前沒有報支記錄";
				return;
			}
			box.innerHTML = "";
			result.data.forEach(function (row) {
				const card = document.createElement("div");
				card.className = "dtsc-card";
				const head = document.createElement("div");
				head.className = "dtsc-card-head";
				const title = document.createElement("span");
				title.textContent = row.name + "｜" + row.amount;
				const badge = document.createElement("span");
				badge.className = "dtsc-badge " + row.state;
				badge.textContent = row.state_label;
				head.appendChild(title);
				head.appendChild(badge);
				card.appendChild(head);
				const lines = [row.date + "｜" + row.category];
				if (row.description) { lines.push(row.description); }
				if (row.payment_method) { lines.push("付款方式：" + row.payment_method); }
				if (row.reject_reason) { lines.push("拒絕理由：" + row.reject_reason); }
				lines.forEach(function (text) {
					const line = document.createElement("div");
					line.className = "dtsc-muted";
					line.textContent = text;
					card.appendChild(line);
				});
				box.appendChild(card);
			});
		}).catch(function () {
			box.textContent = "查詢失敗，請稍後再試";
		});
	}

	async function submit() {
		showError("");
		const payload = {
			expense_date: document.getElementById("expense_date").value,
			category: document.getElementById("category").value,
			amount: document.getElementById("amount").value,
			description: document.getElementById("description").value.trim(),
		};
		if (!payload.expense_date) { return showError("請選擇日期"); }
		if (!payload.category) { return showError("請選擇類別"); }
		if (!(parseInt(payload.amount, 10) > 0)) { return showError("請輸入正確金額"); }

		const btn = document.getElementById("submit_btn");
		btn.disabled = true;
		btn.textContent = "送出中...";
		try {
			payload.files = [];
			for (const file of selectedFiles) {
				payload.files.push(await encodeFile(file));
			}
			const result = await postJSON("/liff_app/api/expense/submit", payload);
			if (!result.success) {
				showError(result.message);
				return;
			}
			alert(result.message);
			document.getElementById("category").value = "";
			document.getElementById("amount").value = "";
			document.getElementById("description").value = "";
			selectedFiles = [];
			renderFiles();
			switchTab("list");
		} catch (err) {
			showError(err.message || "送出失敗，請稍後再試");
		} finally {
			btn.disabled = false;
			btn.textContent = "送出";
		}
	}

	document.getElementById("expense_date").value = today();
	document.querySelectorAll(".dtsc-tab").forEach(function (btn) {
		btn.addEventListener("click", function () { switchTab(btn.dataset.tab); });
	});
	fileInput.addEventListener("change", function () {
		const incoming = Array.from(fileInput.files);
		fileInput.value = "";
		showError("");
		for (const file of incoming) {
			if (selectedFiles.length >= MAX_FILES) {
				showError("附件最多 " + MAX_FILES + " 個");
				break;
			}
			if (file.type.indexOf("image/") !== 0 && file.type !== "application/pdf") {
				showError(file.name + " 不是圖片或 PDF");
				continue;
			}
			selectedFiles.push(file);
		}
		renderFiles();
	});
	document.getElementById("submit_btn").addEventListener("click", submit);

	window.dtscLiffReady.then(function () {
		if (!liff.isLoggedIn()) {
			liff.login();
			return;
		}
		idToken = liff.getIDToken();
		if (!idToken) {
			showError("通用入口缺少身分驗證權限，請管理員在 Line 設定再按一次「自動創建通用入口」。");
			document.getElementById("submit_btn").disabled = true;
			return;
		}
		if (new URLSearchParams(location.search).get("tab") === "list") {
			switchTab("list");
		}
	});
})();


(function () {
	const expenseId = new URLSearchParams(location.search).get("expense_id");
	const btn = document.getElementById("submit_btn");
	let idToken = null;

	function showError(msg) {
		const box = document.getElementById("error_box");
		box.textContent = msg || "";
		box.style.display = msg ? "block" : "none";
	}

	function postJSON(url, payload) {
		return fetch(url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(Object.assign({ id_token: idToken, expense_id: expenseId }, payload)),
		}).then(function (resp) { return resp.json(); });
	}

	function renderSummary(data) {
		const box = document.getElementById("summary");
		box.innerHTML = "";
		[
			data.name + "｜" + data.state_label,
			"申請人：" + data.employee,
			"日期：" + data.date + "｜" + data.category,
			"金額：" + data.amount,
			"說明：" + (data.description || "（無）"),
		].forEach(function (text) {
			const line = document.createElement("div");
			line.textContent = text;
			box.appendChild(line);
		});
	}

	btn.addEventListener("click", function () {
		const reason = document.getElementById("reason").value.trim();
		if (!reason) {
			return showError("請填寫拒絕理由");
		}
		showError("");
		btn.disabled = true;
		postJSON("/liff_app/api/expense/reject", { reason: reason }).then(function (result) {
			if (!result.success) {
				showError(result.message);
				btn.disabled = false;
				return;
			}
			alert(result.message);
			liff.closeWindow();
		}).catch(function () {
			showError("送出失敗，請稍後再試");
			btn.disabled = false;
		});
	});

	window.dtscLiffReady.then(function () {
		if (!liff.isLoggedIn()) {
			liff.login();
			return;
		}
		idToken = liff.getIDToken();
		if (!idToken) {
			showError("通用入口缺少身分驗證權限，請管理員在 Line 設定再按一次「自動創建通用入口」。");
			return;
		}
		postJSON("/liff_app/api/expense/detail", {}).then(function (result) {
			if (!result.success) {
				document.getElementById("summary").textContent = result.message;
				return;
			}
			renderSummary(result.data);
			if (result.data.state === "to_approved") {
				btn.disabled = false;
			} else {
				showError("這張報支單已經簽核過了");
			}
		});
	});
})();
